package in.workshopdesk.app;
import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.graphics.Color;import android.webkit.*;import android.view.*;import android.widget.*;import android.print.*;import java.io.*;
public class MainActivity extends Activity {
 private WebView web;private static final String HOME="https://workshop-desk.web.app/";private static final int PICK=7;private ValueCallback<Uri[]> upload;
 private boolean trusted(String url){try{Uri u=Uri.parse(url);return "https".equals(u.getScheme())&&"workshop-desk.web.app".equals(u.getHost());}catch(Exception e){return false;}}
 public void onCreate(Bundle state){super.onCreate(state);getWindow().setStatusBarColor(Color.rgb(30,43,64));getWindow().setNavigationBarColor(Color.rgb(30,43,64));
  web=new WebView(this);web.setBackgroundColor(Color.rgb(228,234,242));setContentView(web);WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(true);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);s.setSupportMultipleWindows(false);s.setMediaPlaybackRequiresUserGesture(true);CookieManager.getInstance().setAcceptCookie(true);
  web.addJavascriptInterface(new PdfBridge(),"WorkshopAndroid");
  web.setWebViewClient(new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){String u=r.getUrl().toString();if(trusted(u))return false;if(!r.isForMainFrame())return true;try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(u)));}catch(Exception e){Toast.makeText(MainActivity.this,"No app available to open this link",Toast.LENGTH_SHORT).show();}return true;}
   public void onPageFinished(WebView v,String u){if(trusted(u)){installSharing();CookieManager.getInstance().flush();}}
   public void onReceivedError(WebView v,WebResourceRequest r,WebResourceError e){if(r.isForMainFrame())new AlertDialog.Builder(MainActivity.this).setTitle("Could not connect").setMessage("Check your internet connection and try again.").setPositiveButton("Retry",(d,w)->web.loadUrl(HOME)).setNegativeButton("Close",(d,w)->finish()).show();}
  });
  web.setWebChromeClient(new WebChromeClient(){public boolean onShowFileChooser(WebView v,ValueCallback<Uri[]> cb,FileChooserParams params){if(upload!=null)upload.onReceiveValue(null);upload=cb;try{startActivityForResult(params.createIntent(),PICK);return true;}catch(Exception e){upload=null;return false;}}
   public boolean onJsAlert(WebView v,String url,String msg,JsResult result){new AlertDialog.Builder(MainActivity.this).setMessage(msg).setPositiveButton("OK",(d,w)->result.confirm()).setOnCancelListener(d->result.cancel()).show();return true;}
   public boolean onJsConfirm(WebView v,String url,String msg,JsResult result){new AlertDialog.Builder(MainActivity.this).setMessage(msg).setPositiveButton("OK",(d,w)->result.confirm()).setNegativeButton("Cancel",(d,w)->result.cancel()).setOnCancelListener(d->result.cancel()).show();return true;}
  });
  web.setDownloadListener((url,ua,disposition,mime,len)->{if(url.startsWith("blob:"))return;try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)));}catch(Exception e){}});
  if(state==null||web.restoreState(state)==null)web.loadUrl(HOME);
 }
 private void installSharing(){web.evaluateJavascript("(function(){if(window.wdAndroidInstalled)return;window.wdAndroidInstalled=true;var style=document.createElement('style');style.textContent='.login-story,.login-note,.login-demo,.login-bottom,.login-form-wrap>.label,.login-form-wrap>p,.login-form-wrap>[data-action=login-reset]{display:none!important}.login-shell{display:flex!important;height:100dvh!important;min-height:0!important;padding:0!important;overflow:hidden!important}.login-form-side{width:100%;height:100%;min-height:0!important;padding:24px!important;box-sizing:border-box}.login-form-wrap{margin:auto!important;padding:0!important;max-width:370px;width:100%}.login-form-wrap:before{content:'';display:block;width:64px;height:64px;margin:0 auto 22px;background:url(https://workshop-desk.web.app/brand-logo.png) center/contain no-repeat}.login-form-wrap h2{text-align:center;font-size:30px;margin:0 0 26px!important}.login-form-wrap form{margin-top:0!important}.login-form-wrap .form-group{margin-bottom:20px!important}.login-form-wrap input{font-size:16px}.login-submit{min-height:46px}.login-shell .login-form-wrap{max-height:100%}.login-shell{position:relative}.login-top{display:flex!important;position:absolute!important;inset:0 0 auto 0!important;justify-content:flex-end!important;min-height:0!important;height:70px!important;padding:16px 22px!important;background:transparent!important;border:0!important;box-shadow:none!important}.login-top>*{display:none!important}.login-top .theme-toggle{display:block!important;margin:0!important;width:76px!important;height:34px!important}.login-form-wrap:before{width:76px;height:76px;background-color:#e9eff6;border-radius:18px;box-shadow:4px 4px 10px #0002;padding:8px;box-sizing:border-box;background-size:60px}.login-form-side{padding-top:76px!important}';document.head.appendChild(style);function send(file){return new Promise(function(resolve,reject){if(!file||file.type!=='application/pdf'||file.size>20000000){reject(new Error('Choose a PDF smaller than 20 MB'));return;}var reader=new FileReader();reader.onload=function(){WorkshopAndroid.sharePdf(file.name,String(reader.result).split(',')[1]);resolve();};reader.onerror=reject;reader.readAsDataURL(file);});}Object.defineProperty(navigator,'canShare',{configurable:true,value:function(d){return !!(d&&d.files&&d.files.length===1&&d.files[0].type==='application/pdf');}});Object.defineProperty(navigator,'share',{configurable:true,value:function(d){return send(d.files&&d.files[0]);}});document.addEventListener('click',function(e){var a=e.target.closest('a[download]');if(a&&a.href.startsWith('blob:')){e.preventDefault();fetch(a.href).then(function(r){return r.blob();}).then(function(b){return send(new File([b],a.download||'Workshop-Desk.pdf',{type:'application/pdf'}));}).catch(function(){alert('Could not prepare PDF. Please try again.');});}},true);window.print=function(){WorkshopAndroid.printPage();};})()",null);}
 public class PdfBridge {
  @JavascriptInterface public void sharePdf(String name,String encoded){runOnUiThread(()->{if(!trusted(web.getUrl())||encoded==null||encoded.length()>28000000)return;new Thread(()->{try{byte[] bytes=android.util.Base64.decode(encoded,android.util.Base64.DEFAULT);if(bytes.length<5||!new String(bytes,0,5,"US-ASCII").equals("%PDF-"))throw new IOException();String safe=(name==null?"Workshop-Desk.pdf":name).replaceAll("[^a-zA-Z0-9._-]","_");if(!safe.endsWith(".pdf"))safe+=".pdf";File dir=new File(getCacheDir(),"pdf");dir.mkdirs();File f=new File(dir,System.currentTimeMillis()+"-"+safe);try(FileOutputStream out=new FileOutputStream(f)){out.write(bytes);}Uri uri=Uri.parse("content://in.workshopdesk.app.pdf/"+Uri.encode(f.getName()));Intent intent=new Intent(Intent.ACTION_SEND);intent.setType("application/pdf");intent.putExtra(Intent.EXTRA_STREAM,uri);intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);intent.setClipData(ClipData.newRawUri("PDF",uri));runOnUiThread(()->startActivity(Intent.createChooser(intent,"Share or save PDF")));}catch(Exception e){runOnUiThread(()->Toast.makeText(MainActivity.this,"Could not share PDF",Toast.LENGTH_LONG).show());}}).start();});}
  @JavascriptInterface public void printPage(){runOnUiThread(()->{if(trusted(web.getUrl()))((PrintManager)getSystemService(PRINT_SERVICE)).print("Workshop Desk",web.createPrintDocumentAdapter("Workshop Desk"),null);});}
 }
 @Override public void onBackPressed(){if(web.canGoBack())web.goBack();else new AlertDialog.Builder(this).setTitle("Close Workshop Desk?").setPositiveButton("Close",(d,w)->finish()).setNegativeButton("Stay",null).show();}
 @Override protected void onSaveInstanceState(Bundle b){web.saveState(b);super.onSaveInstanceState(b);}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==PICK&&upload!=null){upload.onReceiveValue(WebChromeClient.FileChooserParams.parseResult(result,data));upload=null;}}
 @Override protected void onDestroy(){web.removeJavascriptInterface("WorkshopAndroid");web.destroy();super.onDestroy();}
}
